const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v===null||v===undefined?'Not recorded':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
const date=v=>v?new Date(`${v.slice(0,10)}T12:00:00`).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):'To be agreed';
const link=(url,label)=>{try{const u=new URL(url);return u.protocol==='https:'?`<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:esc(label);}catch{return esc(label);}};
const pill=(text)=>`<span class="pill ${text==='Paid'||text==='Complete'?'paid-pill':'neutral'}">${esc(text||'Not recorded')}</span>`;
const empty=text=>`<p class="empty-state">${esc(text)}</p>`;
function table(heads,rows){return `<div class="table-scroll"><table class="portal-table"><thead><tr>${heads.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
let authenticated=false, busy=false, failure=false, lastData=null;
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});const data=await response.json();if(!response.ok){const error=new Error(data.error||'Request failed');error.status=response.status;throw error;}return data;}
function lock(message='Enter your project password to continue.'){
  authenticated=false;lastData=null;$('dashboard').hidden=true;$('gate').hidden=false;$('logout').hidden=true;$('notice').hidden=true;$('gate-message').textContent=message;
  for(const id of ['progress','updates','milestones','assets','downloads','financials','payments','ffe','access'])$(id).replaceChildren();
  for(const id of ['project-name','address','summary','milestone','status','phase','lead','area','allowance','procurement'])$(id).textContent='';
  $('hero-image').removeAttribute('src');$('hero-image').hidden=true;$('image-placeholder').hidden=false;$('footer-project').textContent='Animate Lot';$('synced').textContent='Private client portal';document.title='Animate Lot — Client Project';
}
function render(data){
  const p=data.project;lastData=data;document.title=`${p.name} — Animate Lot`;
  $('project-name').textContent=p.name;$('address').textContent=p.address||'';$('status').textContent=p.status||'';$('phase').textContent=p.phase||'';$('lead').textContent=p.lead?.name||'Animate Lot';
  $('area').textContent=p.area?`${p.area.toLocaleString()} sq. ft.`:'Project overview';$('summary').textContent=p.summary||'';$('milestone-heading').textContent=p.phase||'Current milestone';$('milestone').textContent=p.milestone||'Next milestone to be agreed';
  const image=$('hero-image');if(p.hero?.url){if(image.getAttribute('src')!==p.hero.url)image.src=p.hero.url;image.hidden=false;$('image-placeholder').hidden=true;}else{image.hidden=true;image.removeAttribute('src');$('image-placeholder').hidden=false;}
  const access=[];if(p.polycam)access.push(link(p.polycam,'View 3D Scan · Polycam'));if(p.cintoo)access.push(link(p.cintoo,'View 3D Scan · Cintoo'));if(p.acc)access.push(link(p.acc,'Project Cloud Portal · Autodesk'));$('access').innerHTML=access.join('');$('access').hidden=!access.length;document.querySelector('.overview').classList.toggle('no-access',!access.length);
  $('progress').innerHTML=data.scopes.length?data.scopes.map(s=>`<article class="progress-card animate"><div class="company">${esc(s.company)}</div><h3>${esc(s.name)}</h3><p>${esc(s.milestone||'')}</p>${pill(s.status)}${s.progress===null?'':`<div class="scope-progress" style="--progress:${s.progress}%"><div class="scope-progress-meta"><span>Studio progress estimate</span><strong>${s.progress}%</strong></div><div class="wave-track" role="progressbar" aria-label="${esc(s.name)} progress" aria-valuenow="${s.progress}" aria-valuemin="0" aria-valuemax="100"><div class="wave-fill"></div></div></div>`}</article>`).join(''):empty('Progress updates will appear when published.');
  $('updates').innerHTML=data.updates.slice(0,5).map(u=>`<article><p class="label">${esc(date(u.date))} · ${esc(u.status)}</p><h3>${esc(u.name)}</h3><p>${esc(u.summary)}</p></article>`).join('');
  $('milestone-section').hidden=!p.showSchedule;$('milestones').innerHTML=data.milestones.length?table(['Milestone','Responsible','Date','Status'],data.milestones.map(m=>[`<strong>${esc(m.name)}</strong><small>${esc(m.notes)}</small>`,esc(m.party),m.status==='Complete'?(m.completed?esc(date(m.completed)):'Complete · date not recorded'):esc(date(m.date)),pill(m.status)])):empty('Milestones will appear when published.');
  $('assets').innerHTML=data.assets.length?table(['Deliverable','Issued','Status','Files'],data.assets.map(a=>[`<strong>${a.url?link(a.url,a.name):esc(a.name)}</strong><small>${esc(a.description)}</small>`,a.issued?esc(date(a.issued)):'Not recorded',pill(a.status),a.files.map(f=>link(f.url,f.name)).join('<br>')||'—'])):empty('Design deliverables are in preparation. Issued files will appear here.');
  $('downloads').innerHTML=data.downloads.length?`<h3 class="table-group">Contract documents</h3>${data.downloads.map(f=>`<p>${link(f.url,f.name)}</p>`).join('')}`:'';
  const financial=data.scopes.filter(s=>s.showFinancials);$('finance-section').hidden=!p.showFinancials;$('payment-section').hidden=!p.showFinancials;
  $('financials').innerHTML=financial.length?financial.map(s=>`<div class="scope-block animate"><div class="scope-title"><div><span>AL</span><p>${esc(s.company)}</p></div>${pill(s.status)}</div><div class="scope-grid"><div><small>Scope</small><strong>${esc(s.name)}</strong></div><div><small>Contract fee</small><strong>${money(s.fee)}</strong></div><div><small>Paid to date</small><strong class="paid-money">${money(s.received)}</strong></div><div><small>Remaining contract fee</small><strong>${money(s.remaining)}</strong></div></div></div>`).join(''):empty('Financial details have not been published.');
  $('payments').innerHTML=data.payments.length?table(['Payment','Type','Amount','Status / due'],data.payments.map(x=>[`<strong>${esc(x.name)}</strong>${x.invoice?`<small>${esc(x.invoice)}</small>`:''}`,esc(x.type),money(x.amount),`${pill(x.status)}${x.due&&x.status!=='Paid'?`<small>Due ${esc(date(x.due))}</small>`:''}`])):empty('No payment records have been published.');
  $('ffe-section').hidden=!p.showFFE;$('allowance').textContent=p.allowance===null?'':`Merchandise planning allowance: ${money(p.allowance)}`;$('procurement').textContent=`Animate Lot procurement: ${p.procurement||'To be confirmed'}. Procured By identifies the purchasing party; it does not authorize an order or a procurement fee. A planning allowance is not a quote or an approved purchase.`;
  $('ffe').innerHTML=table(['Item','Vendor / quantity','Procured By','Price','Selection status'],data.ffe.map(x=>[`<strong>${x.url?link(x.url,x.name):esc(x.name)}</strong><small>${esc([x.room,x.manufacturer,x.model].filter(Boolean).join(' · '))}</small><small>${esc(x.notes)}</small>`,`${esc(x.vendor||'To be confirmed')}<small>${x.qty===null?'Quantity not recorded':esc(`${x.qty} ${x.unit||''}`)}</small>`,pill(x.procuredBy||'Unassigned'),x.price===null?'Not published':money(x.price),pill(x.delivered?'Delivered':x.ordered?'Ordered':x.approved?'Approved':'For review')]))+(data.ffe.length?'':empty('Selections are being developed. Products and their purchasing parties will appear here when shared for review.'));
  $('footer-project').textContent=p.name;$('synced').textContent=p.lastUpdated?`Project update · ${date(p.lastUpdated)}`:'Live project data';
  $('gate').hidden=true;$('dashboard').hidden=false;$('logout').hidden=false;$('notice').hidden=true;failure=false;
}
async function refresh(){if(busy||!authenticated)return;busy=true;try{render(await api('/api/project'));}catch(error){if(error.status===401){lock('Your session has ended. Please sign in again.');}else{failure=true;$('notice').hidden=false;$('notice').textContent=lastData?'Connection interrupted. Showing the last successfully loaded information; retrying while this page is open.':'The project connection is not ready. Please retry shortly.';if(!lastData)$('gate-message').textContent='Signed in, but project data could not load. The Notion connection may need configuration.';}}finally{busy=false;}}
$('login').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;$('gate-message').textContent='Opening your dashboard…';try{await api('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('password').value})});$('password').value='';authenticated=true;await refresh();}catch(error){$('gate-message').textContent=error.message;}finally{button.disabled=false;}});
$('logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST'});lock();}catch{$('notice').hidden=false;$('notice').textContent='Sign out did not complete. Please retry.';}});
$('hero-image').addEventListener('error',()=>{$('hero-image').hidden=true;$('image-placeholder').hidden=false;});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
setInterval(()=>{if(!document.hidden)refresh();},60000); // Only an open, signed-in dashboard refreshes. No keep-alive service.
try{const session=await api('/api/session');if(session.authenticated){authenticated=true;await refresh();}else lock(session.ready?'Enter your project password to continue.':'This portal is awaiting its Notion connection and access settings.');}catch{lock('The project connection is temporarily unavailable. Please reload shortly.');}
